"""Build the offline review hub from this review's Markdown and JSON only."""
import html,json,os,re
from pathlib import Path
import markdown
from bs4 import BeautifulSoup

OUT=Path(__file__).resolve().parents[1]
WT=OUT.parents[1]
DOC=WT/'docs/research/anime-pipeline-total-review'
DOC.mkdir(parents=True,exist_ok=True)
E=html.escape
def read(name): return json.loads((OUT/name).read_text())
def href(path,base=DOC): return os.path.relpath(path,base)
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{overflow-wrap:anywhere;margin:0;background:#f6f3ed;color:#202a31;font:17px/1.6 system-ui,sans-serif}a{color:#125769;text-underline-offset:3px}a:hover{color:#812e13}a:focus-visible,button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #bc481b;outline-offset:4px}header,main,footer{max-width:1200px;margin:auto;padding:24px 32px}header{border-bottom:1px solid #cfc7b9}nav{display:flex;flex-wrap:wrap;gap:10px 20px}nav a{padding:5px 0}h1{font-size:clamp(2rem,4.5vw,3.6rem);line-height:1.1;letter-spacing:-.035em;max-width:1000px}h2{font-size:1.75rem;line-height:1.2;margin-top:0}h3{line-height:1.3}p{max-width:85ch}section{margin:0 0 38px;padding-top:25px;border-top:1px solid #d5cec1}.eyebrow{font-size:.78rem;font-weight:750;letter-spacing:.15em;text-transform:uppercase;color:#42646a}.hero{padding:22px 0 26px;border-top:0}.lead{font-size:1.2rem;max-width:75ch}.notice{border-left:5px solid #ae4d1d;padding:12px 18px;background:#fff2dc}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:18px}.card{background:#fffdfa;border:1px solid #d5cec1;border-radius:8px;padding:20px;min-width:0}.stat{font-size:2.1rem;font-weight:750;line-height:1.1}.muted,small{color:#526069}.tag{font-size:.78rem;padding:3px 8px;background:#e4eeeb;display:inline-block;border-radius:4px}.table-wrap{overflow-x:auto;max-width:100%;border:1px solid #d5cec1;border-radius:6px}table{border-collapse:collapse;width:100%;font-size:.94rem}th,td{text-align:left;padding:12px;vertical-align:top;border-bottom:1px solid #ddd5c9;overflow-wrap:anywhere}th{background:#e8e6df;color:#253f47}tbody tr:nth-child(even){background:#fffdf8}code{font-size:.84em;overflow-wrap:anywhere}pre{background:#ece9e1;padding:16px;overflow:auto;max-width:100%}blockquote{border-left:3px solid #75939a;margin-left:0;padding-left:18px}img,svg{max-width:100%;height:auto}ul,ol{padding-left:24px}li{margin:6px 0}details{margin:12px 0;padding:13px 16px;border:1px solid #d2cabd;border-radius:6px;background:#fffdf8}summary{font-weight:700;cursor:pointer}select{width:100%;min-width:0}select,button{font:inherit;padding:10px;border:1px solid #8b9695;border-radius:5px;background:white;color:#202a31;max-width:100%}.controls{display:flex;flex-wrap:wrap;gap:18px;margin:18px 0}.controls label{display:grid;gap:5px;flex:1 1 200px;min-width:0}.scorebar{display:block;width:100%;height:6px;background:#e0e3df;margin-top:6px}.scorebar span{display:block;height:100%;background:#246577}.pill{display:inline-block;margin:4px;padding:5px 10px;background:#e5ebe6;border-radius:20px}.skip{position:absolute;left:-10000px}.skip:focus{position:fixed;left:12px;top:12px;background:white;z-index:5;padding:12px}.report{max-width:1000px}.report a{overflow-wrap:anywhere}.report h2{margin-top:40px}.report h1{font-size:2.7rem}.report table{min-width:600px}footer{border-top:1px solid #cfc7b9;font-size:.9rem}@media(max-width:600px){header,main,footer{padding:18px 14px}h1{font-size:2.25rem}.report h1{font-size:2rem}h2{font-size:1.5rem}.card{padding:16px}nav{gap:6px 14px;font-size:.95rem}th,td{padding:9px;font-size:.9rem}.hero{padding-top:8px}.lead{font-size:1.08rem}.score-details{min-width:490px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
(DOC/'review.css').write_text(CSS)
def shell(title,body,base=DOC,report=False):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} · Pipeline review</title><link rel="stylesheet" href="{href(DOC/'review.css',base)}"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="eyebrow">Independent production audit · September 2026</div><nav aria-label="Review navigation"><a href="{href(DOC/'index.html',base)}">Review hub</a><a href="{href(DOC/'reports/executive-decision.html',base)}">Decision</a><a href="{href(DOC/'reports/next-pilot-specification.html',base)}">Pilot plan</a><a href="{href(DOC/'pilot-proof.html',base)}">Rough proof</a><a href="{href(DOC/'reports/changed-files-and-integrity.html',base)}">Integrity</a></nav></header><main id="main" class="{'report' if report else ''}">{body}</main><footer>Original analysis; no third-party comic panels redistributed. $0 incremental paid/cloud spend. AI reviews are not human acceptance. Source and rights limits remain explicit.</footer></body></html>'''
mdfiles=sorted(list(OUT.glob('*.md'))+list((OUT/'evidence').glob('*.md')))
def report_path(f):return DOC/'reports'/f.relative_to(OUT).with_suffix('.html')
def transform_md(f):
 target=report_path(f);target.parent.mkdir(parents=True,exist_ok=True)
 soup=BeautifulSoup(markdown.markdown(f.read_text(),extensions=['tables','fenced_code','toc']),'html.parser')
 for a in soup.select('a[href]'):
  raw=a['href']
  if re.match(r'^(https?:|mailto:|#)',raw):continue
  path,sep,frag=raw.partition('#');path=re.sub(r':\d+$','',path)
  src=(f.parent/path).resolve() if not path.startswith('/') else Path(path)
  if src.suffix=='.md' and src.is_relative_to(OUT) and src in mdfiles:dest=report_path(src);a['href']=href(dest,target.parent)+(sep+frag if sep else '')
  elif src.is_relative_to(WT):a['href']=href(src,target.parent)+(sep+frag if sep else '')
  else:a['href']=src.as_uri()+(sep+frag if sep else '')
 for table in soup.find_all('table'):
  wrap=soup.new_tag('div',attrs={'class':'table-wrap','tabindex':'0','role':'region','aria-label':'Scrollable data table'});table.wrap(wrap)
 title=soup.h1.get_text() if soup.h1 else f.stem
 body=f'<p><a href="{href(f,target.parent)}">Markdown source</a></p>'+str(soup)
 target.write_text(shell(title,body,target.parent,True))
for f in mdfiles:transform_md(f)
def report(n,label=None):return f'<a href="reports/{n}.html">{E(label or n.replace("-"," "))}</a>'
inv=read('pipeline-inventory.json');scores=read('pipeline-scorecards.json');causes=read('causal-gap-tree.json');strategies=read('strategy-decision-matrix.json');derivation=read('inspiration-derivation-matrix.json');citations=read('citation-ledger.json');readers=read('evidence/reader-paths.json')['readers'];plan=read('next-pilot-plan.json')
body='''<section class="hero" id="verdict"><div class="eyebrow">The decision</div><h1>Rebuild the sequence process.<br>Keep Ember on probation.</h1><p class="lead">Replace storyboard, source-selection and acceptance stages first. Keep the current renderer as a fair control: its replacement has not been proven necessary. A new story would inherit the demonstrated production errors.</p><p><span class="tag">Primary: B · modular replacement</span> <span class="tag">Fallback: C · human-directed, if staffed</span></p><p>''' +report('executive-decision','Read the executive decision')+' · '+report('strategy-decision-matrix','Compare all four strategies')+'''</p><aside class="notice"><strong>Preservation exception disclosed.</strong> Eight prior trees passed; one prior review branch changed concurrently. The raw strict result remains FAIL. The owner authorized completion subject to independent analysis. '''+report('evidence/independence-and-authorization','Read the independence controls and limits')+'''</aside></section><nav aria-label="Hub sections"><a href="#evidence">Evidence</a><a href="#genealogy">Genealogy</a><a href="#scores">Scores</a><a href="#causes">Failure map</a><a href="#readers">Readers</a><a href="#industry">Industry</a><a href="#strategies">Strategies</a><a href="#pilot">Next pilot</a><a href="#sources">Sources</a><a href="#reports">All reports</a></nav>'''
body+='''<section id="evidence"><h2>The gap is causal, not just cosmetic</h2><div class="grid"><div class="card"><div class="stat">52 unique</div><p>Source hashes pass. Yet P012 asks for four adults where the chapter needs two; P037 selects monster aftermath before the finishing blow.</p></div><div class="card"><div class="stat">89.095</div><p>Identical mean, median and weakest-panel preset score. It is evidence about the scoring code, not independent quality.</p></div><div class="card"><div class="stat">9.40 → 12.30px</div><p>Matched minimum type at 362px art width improved. Curved-balloon spills and face-covering UI still ship.</p></div><div class="card"><div class="stat">32,639px</div><p>Latest true-phone scroll height, 52 panels. All 104 art/overlay elements loaded on the corrected pass; file payload about 129.4 MB, not network timing.</p></div></div><p>These are bounded observations and measurements. Darkness and edge density do not measure beauty. Strong faces, monster scale and some contacts remain worth retaining.</p>'''+report('visual-sequential-audit','Visual evidence')+' · '+report('lettering-ui-mobile-audit','Matched lettering audit')+' · '+report('validation-goodhart-audit','Why checks false-pass')+'</section>'
body+='<section id="genealogy"><h2>Twenty mechanisms, not twenty fresh starts</h2><p>New branches often inherit the same finished-image selection and assembly process. The complete inventory maps source inputs, repairs, owner feedback and stage inheritance. Control/previz mechanisms are not scored as failed finished comics.</p><div class="grid">'
for p in inv['pipelines']:
 body+=f'<details><summary>{E(p["identifier"])} · {E(p["story"])}</summary><p>{E(p["intended_hypothesis"])}</p><p><strong>Inherited:</strong> {E(str(p["inherited_from"]))}</p><p><strong>Page result:</strong> {E(str(p["whether_inheritance_improved_page"]))}</p></details>'
body+='</div><p>'+report('pipeline-inventory','Full chronology and stage maps')+'</p></section>'
body+='''<section id="scores"><h2>Independent scores, visible disagreement</h2><p>Two AI task passes; no human audience validation. Of 285 paired dimensions, 176 agree and 109 differ by at least one point (maximum 2). No weighted total is supplied because production fitness is unassessed. Preserve critical failures instead of averaging them away.</p><div class="controls"><label>Pipeline<select id="pipeline-select">'''
for p in scores['records']:body+=f'<option value="{E(p["pipeline_id"])}" {"selected" if p["pipeline_id"]=="editorial52" else ""}>{E(p["pipeline_id"]+" · "+p["title"])}</option>'
body+='</select></label><label>Category<select id="category-select">'
for c in read('common-rubric.json')['dimensions']:body+=f'<option value="{c}" {"selected" if c=="sequential_storytelling" else ""}>{E(c.replace("_"," "))}</option>'
body+='</select></label></div><div id="score-output" aria-live="polite"></div><p>'+report('pipeline-scorecards','All judgments, evidence and minority views')+' · '+report('evidence/visual-review-b','Independent B visual notes')+'</p></section>'
body+='<section id="causes"><h2>Where the page fails</h2><p>Narrative intent → storyboard → source request → selection → repair → lettering → acceptance → phone reader. Fix the earliest demonstrated error; later polish cannot change the event depicted.</p><div class="grid">'
for n in causes['nodes']:
 body+=f'<article class="card"><span class="tag">{E(n["id"])} · {E(n["severity"])}</span><h3>{E(n["symptom"])}</h3><p><strong>Stage:</strong> {E(n["earliest_stage"])}</p><p>{E(n["cause"])}</p><p><strong>Change:</strong> {E(n["remedy"])}</p></article>'
body+='</div><p>'+report('causal-gap-tree','Evidence and competing explanations')+' · '+report('technical-pipeline-audit','Source-level audit')+'</p></section>'
body+='<section id="readers"><h2>Inspect the actual protected readers</h2><p>These links open existing local art in place. Nothing is copied into this package. Availability does not mean every panel was individually scored; see the sampled coverage and browser corrections.</p><details><summary>All 39 existing reading surfaces</summary><ul>'
for r in readers:body+=f'<li><a href="{E(Path(r["path"]).as_uri())}">{E(r["id"])}</a> — {E(r["kind"])}. {E(r.get("notes",""))}</li>'
body+='</ul></details><p>'+report('browser-qa','Browser checks and limitations')+' · '+report('visual-sequential-audit','Sampling coverage')+'</p></section>'
body+='''<section id="industry"><h2>Use professional craft, not a copied surface style</h2><p>Storyboard approval, clear role handoffs, editable lettering, deliberate contact/acting corrections and destination-specific delivery checks are transferable. Published credits establish roles; they do not establish a universal staff size, cost or cadence.</p><p>Licensed Tower of God and Solo Leveling samples support targeted observations about desire, reveals, escalation and attention. Detailed later Tower of God art and Solo Leveling’s implied impacts challenge a universal “sparse cel art plus every action beat” prescription. ORV was synopsis-only and unscored. These are bounded samples, not whole-series ratings.</p>'''+report('industry-research','Primary-source industry review')+' · '+report('comparable-works-analysis','Licensed sample analysis')+' · '+report('economics-rights-risk','Economics and rights')+'<div class="grid">'
for row in derivation['rows']:
 body+=f'<details><summary>{E(row["generalized_principle"])}</summary><p><strong>Observed:</strong> {E(row["observed_high_level_quality"])}</p><p><strong>Original application:</strong> {E(row["original_improvement_direction"])}</p><p>{E(str(row.get("prohibited_similarity","")))}</p></details>'
body+='</div><p>'+report('inspiration-derivation-matrix','Full derivation and prohibited similarity matrix')+'</p></section>'
body+='<section id="strategies"><h2>A fair choice among four paths</h2><div class="controls"><label>Strategy<select id="strategy-select">'
for s in strategies['strategies']:body+=f'<option value="{s["id"]}" {"selected" if s["id"]=="B" else ""}>{E(s["id"]+" · "+s["name"])}</option>'
body+='</select></label></div><div id="strategy-output" aria-live="polite"></div><p>Ranges are planning estimates, not logged human time or permission to hire. All production routes remain unrun. A qualifies independently and wins a tie if cheaper; B/C must demonstrate a meaningful improvement.</p><p>'+report('strategy-decision-matrix','Every criterion and ranking lens')+' · '+report('red-team-review','Strongest case against B')+' · '+report('recommended-roadmap','30/90-day gates')+'</p></section>'
body+='''<section id="pilot"><h2>Next: fourteen panels, one consequential escape</h2><p><strong>Three Charges, One Dose.</strong> Two original adults protect a sealed flask. A counter earns Air Brake; its first use changes the fight. A broken staff and injured hand persist into a quiet aftermath. This neutral capability scene separates route quality from Ember attachment.</p><div class="grid"><div class="card"><h3>Equal direction</h3><p>Best-current A versus controlled separable B. Same beats, layout, copy, camera, assets, rubric and budgets. Human-first C only when skilled capacity exists.</p></div><div class="card"><h3>Bounded attempts</h3><p>One primary candidate plus one targeted hard-failure retry per panel/group; one correction round. No beauty loops. $0 incremental paid/cloud spend.</p></div><div class="card"><h3>Human gate</h3><p>Zero semantic, lettering or delivery hard failures. Two independent humans pass comprehension and required dimensions; owner must want to continue. B/C promotion needs explicit preference and predeclared improvement.</p></div></div><p><a href="pilot-proof.html">Open the original static vector storyboard and lettering stress proof</a> · '''+report('next-pilot-specification','Read exact acceptance and kill gates')+'''</p><p class="notice">The rough proof tests a reviewable plan/layout only. It is unaccepted, commercially uncleared and not a production base. It does not prove generated artwork, a route winner, human hours or actual localization. A winning production pilot authorizes only a bounded Ember opening and separately agreed throughput proof, never another ten-chapter volume.</p></section>'''
body+='<section id="sources"><h2>Sources, limits and integrity</h2><p>36 source records preserve claim scope, authority, dates and access limits. Update dates are distinguished from publication dates; method-specific HEAD failures do not negate successful page reads. No third-party art is embedded.</p><details><summary>Browse all source records</summary><ol>'
for c in citations['sources']:
 body+=f'<li><a href="{E(c["url"])}">{E(c["title"])}</a><br><small>{E(str(c.get("publisher_author",c.get("publisher",""))))} · {E(str(c.get("source_type","")))} · accessed {E(str(c.get("access_date","unknown")))}</small></li>'
body+='</ol></details><p><a href="'+href(OUT/'citation-ledger.json')+'">Machine citation ledger</a> · '+report('limitations-and-open-questions','Evidence limits')+' · '+report('changed-files-and-integrity','Files, preservation and Git handoff')+' · '+report('evidence/independence-and-authorization','Independence disclosure')+'</p></section>'
body+='<p>'+report('cleanup-and-astra-next-steps','Cleanup, Astra and the next production path')+'</p>'
body+='<section id="reports"><h2>Complete report library</h2><ul>'
for f in mdfiles:
 if f.parent==OUT:body+=f'<li>{report(f.stem)}</li>'
body+='</ul></section>'
data={'scores':scores['records'],'strategies':strategies['strategies']}
(DOC/'hub-data.js').write_text('window.REVIEW='+json.dumps(data,ensure_ascii=False).replace('</',r'<\/')+';\n')
JS='''const esc=s=>String(s??'Not assessed').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function score(){const p=REVIEW.scores.find(x=>x.pipeline_id===document.querySelector('#pipeline-select').value),key=document.querySelector('#category-select').value,c=p.categories[key];let h=`<div class="grid"><div class="card"><strong>Lead A: ${esc(c.A_mean)} / 5</strong><p>Coverage ${esc(c.A_coverage)}</p></div><div class="card"><strong>Independent B: ${esc(c.B_mean)} / 5</strong><p>Coverage ${esc(c.B_coverage)}</p></div></div><div class="table-wrap" tabindex="0" role="region" aria-label="Dimension score comparison"><table class="score-details"><thead><tr><th>Dimension</th><th>A</th><th>B</th><th>Difference</th></tr></thead><tbody>`;for(const d of c.dimensions)h+=`<tr><td>${esc(d.dimension)}<details><summary>Reasons</summary><p><strong>A:</strong> ${esc(d.justification_A)}</p><p><strong>B:</strong> ${esc(d.justification_B)}</p></details></td><td>${esc(d.A)}</td><td>${esc(d.B)}</td><td>${esc(d.absolute_disagreement)}</td></tr>`;document.querySelector('#score-output').innerHTML=h+'</tbody></table></div>'}
function strategy(){const s=REVIEW.strategies.find(x=>x.id===document.querySelector('#strategy-select').value);let h=`<article class="card"><h3>${esc(s.id)} · ${esc(s.name)}</h3><div class="grid">`;for(const k of ['retain','replace','quality_ceiling','owner_fit','roles','human_hours_estimate','risks','kill','scale'])if(k in s)h+=`<div><strong>${esc(k.replaceAll('_',' '))}</strong><p>${esc(Array.isArray(s[k])?s[k].join(' – '):s[k])}</p></div>`;document.querySelector('#strategy-output').innerHTML=h+'</div></article>'}
document.querySelector('#pipeline-select').addEventListener('change',score);document.querySelector('#category-select').addEventListener('change',score);document.querySelector('#strategy-select').addEventListener('change',strategy);score();strategy();
'''
(DOC/'hub.js').write_text(JS)
body+='<script src="hub-data.js"></script><script src="hub.js"></script>'
(DOC/'index.html').write_text(shell('Rebuild the sequence process',body))
print(json.dumps({'reports':len(mdfiles),'hub':str(DOC/'index.html'),'offline':True}))
